#include "harmonylightpalette.h"
#include <cassert>
#include <iostream>
int main(int argc,char**argv){QApplication app(argc,argv);app.setStyle("Fusion");QPalette fixed=app.style()->standardPalette();fixed.setColor(QPalette::Text,QColor("#202124"));fixed.setColor(QPalette::ButtonText,QColor("#202124"));app.setPalette(fixed);app.setProperty("harmonyLightPalette",QVariant::fromValue(fixed));HarmonyLightPaletteGuard guard(&app);QComboBox combo;combo.addItem("test");combo.show();QPalette blue=fixed;blue.setColor(QPalette::Text,Qt::blue);blue.setColor(QPalette::ButtonText,Qt::blue);QApplication::setPalette(blue,"QComboBox");QApplication::setPalette(blue);for(int i=0;i<5;++i)app.processEvents();assert(combo.palette().color(QPalette::Text)==fixed.color(QPalette::Text));QComboBox next;next.show();QEvent theme(QEvent::ThemeChange);QApplication::sendEvent(&next,&theme);for(int i=0;i<5;++i)app.processEvents();assert(next.palette().color(QPalette::ButtonText)==fixed.color(QPalette::ButtonText));std::cout<<"PASS: platform and per-class palette reset, later-created controls\n";}
